package app.citti.core.auth

import javax.crypto.Cipher
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

/** The ciphertext is unreadable: wrong key, truncated, or modified. */
class CredentialDecryptException(
    cause: Throwable? = null,
) : Exception("Cannot decrypt the stored credentials", cause)

/**
 * AES-256-GCM with a fresh random IV per message, stored as `iv || ciphertext+tag`.
 * Pure `javax.crypto`; [keyProvider] supplies the key (Android Keystore, or a generated key in tests).
 * The IV is generated by the cipher provider (required by Keystore keys), never chosen by us.
 */
class AesGcmCipher(
    private val keyProvider: () -> SecretKey,
) {
    fun encrypt(plain: ByteArray): ByteArray {
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.ENCRYPT_MODE, keyProvider())
        return cipher.iv + cipher.doFinal(plain)
    }

    fun decrypt(data: ByteArray): ByteArray {
        if (data.size <= IV_BYTES) throw CredentialDecryptException()
        try {
            val cipher = Cipher.getInstance(TRANSFORMATION)
            cipher.init(Cipher.DECRYPT_MODE, keyProvider(), GCMParameterSpec(TAG_BITS, data, 0, IV_BYTES))
            return cipher.doFinal(data, IV_BYTES, data.size - IV_BYTES)
        } catch (e: java.security.GeneralSecurityException) {
            throw CredentialDecryptException(e)
        }
    }

    private companion object {
        const val TRANSFORMATION = "AES/GCM/NoPadding"
        const val IV_BYTES = 12
        const val TAG_BITS = 128
    }
}
